def solve(nums, k):
    n = len(nums)
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sorted_nums = sorted(counts.keys())

    current_count = 0
    for num in sorted_nums:
        current_count += counts[num]
        if current_count >= k:
            return num
    return sorted_nums[-1]
```

