def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: float('inf') for i in range(n)}
    dist[s] = 0
    visited = [False] * n
    queue = [s]

    while queue:
        u = queue.pop(0)
        if visited[u]:
            continue
        visited[u] = True

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
