    if s == t:
        return 0

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    dist = {}
    for i in range(n):
        dist[i] = float('inf')
    dist[s] = 0

    visited = [False] * n
    queue = [s]
    visited[s] = True

    while queue:
        u = queue.pop(0)

        if u in graph:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
