def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    needle_counts = {}
    for char in needle:
        needle_counts[char] = needle_counts.get(char, 0) + 1

    window_counts = {}
    for i in range(len(haystack)):
        char = haystack[i]
        window_counts[char] = window_counts.get(char, 0) + 1

        if i >= len(needle):
            left_char = haystack[i - len(needle)]
            window_counts[left_char] -= 1
            if window_counts[left_char] == 0:
                del window_counts[left_char]

        if window_counts == needle_counts:
            return i - len(needle) + 1

    return -1
