def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    queue = deque([start])
    visited = {start}
    path = {start: None}

    while queue:
        curr = queue.popleft()
        if curr == goal:
            result = [goal]
            while curr != start:
                curr = path[curr]
                result.insert(0, curr)
            return result

        r, c = curr
        neighbors = [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]

