from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    queue = deque([start])
    visited = {start}
    path = {}

    while queue:
        curr = queue.popleft()
        row, col = curr

        if curr == goal:
            result = [goal]
            while curr != start:
                curr = path[curr]
                result.insert(0, curr)
            return result

        neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]
        for nr, nc in neighbors:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                queue.append((nr, nc))
                visited.add((nr, nc))
                path[(nr, nc)] = curr

    return []
