def solve(n, edges):
    if n <= 1:
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n

    def has_cycle(node):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if has_cycle(neighbor):
                    return True
            elif neighbor != parent[node]:
                return True
        return False

    parent = [-1] * n
    for i in range(n):
        if not visited[i]:
            if has_cycle(i):
                return True
    return False
